fn cell(m: List[List[Int]], r: Int, c: Int) -> Int {
  return m.get_or(r, []).get_or(c, 0)
}

pub fn spiral(m: List[List[Int]]) -> List[Int] {
  var out: List[Int] = []
  var top = 0
  var bottom = m.len() - 1
  var left = 0
  var right = m.get_or(0, []).len() - 1
  while top <= bottom and left <= right {
    for c in range(left, right + 1) {
      out = out.push(cell(m: m, r: top, c: c))
    }
    top = top + 1
    for r in range(top, bottom + 1) {
      out = out.push(cell(m: m, r: r, c: right))
    }
    right = right - 1
    if top <= bottom {
      for c in range(left, right + 1).reverse() {
        out = out.push(cell(m: m, r: bottom, c: c))
      }
      bottom = bottom - 1
    }
    if left <= right {
      for r in range(top, bottom + 1).reverse() {
        out = out.push(cell(m: m, r: r, c: left))
      }
      left = left + 1
    }
  }
  return out
}
